import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture, vec3 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Mesh, PlaneGeometry, Group } = ctx.THREE;

  const group = new Group();
  group.position.set(3.2, -0.3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Plane geometry: 2.0 x 1.25 units (512x320 aspect ratio)
  const geometry = new PlaneGeometry(2.0, 1.25);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    side: ctx.THREE.FrontSide,
    toneMapped: true,
  });

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Load brushed-metal texture
  ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((brushedMetalTex) => {
      brushedMetalTex.colorSpace = 'srgb';
      brushedMetalTex.magFilter = ctx.THREE.LinearFilter;
      brushedMetalTex.minFilter = ctx.THREE.LinearMipmapLinearFilter;

      // Create TSL nodes for material
      const uvNode = uv();
      const texNode = texture(brushedMetalTex, uvNode);

      // Apply texture to material
      material.colorNode = texNode;
      material.needsUpdate = true;
    })
    .catch((err) => {
      console.error('Failed to load brushed-metal texture:', err);
    });

  // Cleanup function
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  // No event handlers required for static composition
  group.userData.handlers = {};

  return group;
}
